swift - <<'EOF' 2>/dev/null
import CoreAudio

var deviceList: AudioObjectPropertyAddress = AudioObjectPropertyAddress(
    mSelector: kAudioHardwarePropertyDevices,
    mScope: kAudioObjectPropertyScopeGlobal,
    mElement: kAudioObjectPropertyElementMain
)

var dataSize: UInt32 = 0
AudioObjectGetPropertyDataSize(AudioObjectID(kAudioObjectSystemObject), &deviceList, 0, nil, &dataSize)
let deviceCount = Int(dataSize) / MemoryLayout<AudioDeviceID>.size
var devices = [AudioDeviceID](repeating: 0, count: deviceCount)
AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject), &deviceList, 0, nil, &dataSize, &devices)

for deviceID in devices {
    // 取名稱
    var nameAddr = AudioObjectPropertyAddress(
        mSelector: kAudioObjectPropertyName,
        mScope: kAudioObjectPropertyScopeGlobal,
        mElement: kAudioObjectPropertyElementMain
    )
    var name: CFString = "" as CFString
    var nameSize = UInt32(MemoryLayout<CFString>.size)
    AudioObjectGetPropertyData(deviceID, &nameAddr, 0, nil, &nameSize, &name)

    // 檢查是否有輸入 channel
    var inputAddr = AudioObjectPropertyAddress(
        mSelector: kAudioDevicePropertyStreamConfiguration,
        mScope: kAudioDevicePropertyScopeInput,
        mElement: kAudioObjectPropertyElementMain
    )
    var inputSize: UInt32 = 0
    AudioObjectGetPropertyDataSize(deviceID, &inputAddr, 0, nil, &inputSize)
    if inputSize > 0 {
        print("ID: \(deviceID)  名稱: \(name)")
    }
}
EOF

