swift - <<'EOF' 2>/dev/null
import CoreAudio

func getDeviceInfo(_ deviceID: AudioDeviceID) {
    // sample rate
    var srAddr = AudioObjectPropertyAddress(
        mSelector: kAudioDevicePropertyNominalSampleRate,
        mScope: kAudioObjectPropertyScopeGlobal,
        mElement: kAudioObjectPropertyElementMain
    )
    var sr: Float64 = 0
    var srSize = UInt32(MemoryLayout<Float64>.size)
    AudioObjectGetPropertyData(deviceID, &srAddr, 0, nil, &srSize, &sr)

    // input channels
    var streamAddr = AudioObjectPropertyAddress(
        mSelector: kAudioDevicePropertyStreamConfiguration,
        mScope: kAudioDevicePropertyScopeInput,
        mElement: kAudioObjectPropertyElementMain
    )
    var streamSize: UInt32 = 0
    AudioObjectGetPropertyDataSize(deviceID, &streamAddr, 0, nil, &streamSize)

    print("ID \(deviceID): sampleRate=\(sr) Hz, inputDataSize=\(streamSize)")
}

