# 用 Swift 直接測試麥克風輸入 level
swift - <<'EOF' 2>/dev/null
import AVFoundation
import Foundation

let engine = AVAudioEngine()
let inputNode = engine.inputNode
let format = inputNode.outputFormat(forBus: 0)
print("格式：\(format.sampleRate) Hz, \(format.channelCount) ch")

var maxLevel: Float = 0.0
inputNode.installTap(onBus: 0, bufferSize: 4096, format: format) { buffer, time in
    let channelData = buffer.floatChannelData![0]
    let frameLength = Int(buffer.frameLength)
    for i in 0..<frameLength {
        let val = abs(channelData[i])
        if val > maxLevel { maxLevel = val }
    }
}

do {
    try engine.start()
    Thread.sleep(forTimeInterval: 3)
    engine.stop()
    print("最大音量 level：\(maxLevel)")
    if maxLevel > 0.001 {
        print("✅ 麥克風有收到聲音")
    } else {
        print("❌ 麥克風沒有偵測到任何聲音（level 接近 0）")
    }
} catch {
    print("錯誤：\(error)")
}
EOF

